import java.util.Scanner;  import calc.basic.BasicCalc; import calc.advanced.AdvancedCalc; import print.display.Display;  public class Multi_Package{      public static void main(String[] args) {          Scanner sc = new Scanner(System.in);         BasicCalc bc = new BasicCalc();         AdvancedCalc ac = new AdvancedCalc();         Display d = new Display();
 int choice;         do {             System.out.println("\n--- Scientific Calculator ---");             System.out.println("1. Add");             System.out.println("2. Subtract");             System.out.println("3. Multiply");             System.out.println("4. Divide");             System.out.println("5. Power");             System.out.println("6. Square Root");             System.out.println("7. Log");             System.out.println("8. Exit");              System.out.print("Enter choice: ");             choice = sc.nextInt();              double a, b, result = 0;              switch (choice) {                  case 1:                     System.out.print("Enter two numbers: ");                     a = sc.nextDouble();                     b = sc.nextDouble();                     result = bc.add(a, b);                     d.showResult(result);                     break;                  case 2:                     System.out.print("Enter two numbers: ");                     a = sc.nextDouble();                     b = sc.nextDouble();                     result = bc.subtract(a, b);                     d.showResult(result);                     break;                  case 3:                     System.out.print("Enter two numbers: ");                     a = sc.nextDouble();                     b = sc.nextDouble();                     result = bc.multiply(a, b);                     d.showResult(result);                     break;                  case 4:                     System.out.print("Enter two numbers: ");                     a = sc.nextDouble();                     b = sc.nextDouble();
                    result = bc.divide(a, b); d.showResult(result);                    break;                  case 5:                     System.out.print("Enter base and exponent: ");                     a = sc.nextDouble();                     b = sc.nextDouble();                     result = ac.power(a, b);                     d.showResult(result);                     break;                  case 6:                     System.out.print("Enter number: ");                     a = sc.nextDouble();                     result = ac.sqrt(a);                     d.showResult(result);                     break;                  case 7:                     System.out.print("Enter number: ");                     a = sc.nextDouble();                     result = ac.log(a);                     d.showResult(result);                     break;                  case 8:                     System.out.println("Exiting...");                     break;                  default:                     System.out.println("Invalid choice");             }          } while (choice != 8);          sc.close();     } }
